def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    seeds = [(y, x) for y in range(H) for x in range(W) if g[y, x] != bg]
    out = np.full_like(g, bg)
    emit(out.copy(), "Clear the canvas to background; each seed pixel will become a 3x3 ring stamp.")
    for (y, x) in seeds:
        c = g[y, x]
        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                yy, xx = y + dy, x + dx
                if not (0 <= yy < H and 0 <= xx < W):
                    continue
                if dy == 0 and dx == 0:
                    continue
                out[yy, xx] = c if (dy != 0 and dx != 0) else 1
        emit(out.copy(), f"Stamp around seed at ({y},{x}): corners {c}, edge-middles 1, centre empty.")
    emit(out.copy(), "All seeds replaced by their stamps.")
    return out
